    private static Review Case(Definition definition, Guard guard, string guid, string method, string testPath,
        string testSha256, string messageSha256, string stackSha256, int line) =>
        new(new Binding(ReportSha256, definition, guid, method, testPath, testSha256), guard, messageSha256, stackSha256, line,
            "C08 and the pinned public constructor/StartAsync XML admit valid construction, default-token start and idempotent running start; stop is terminal.",
            guard == Guard.PositiveClock
                ? "The exact receiving source constructs the server. Prior source/options validation completed; the reversed guard proves a positive frequency read. System/default and legitimate supplied clocks are admitted, without inventing a historical numeric frequency."
                : "The exact receiving source calls StartAsync() without a token. Its default token is uncanceled and the pinned real live-server arrangement uses no field injection.",
            guard switch
            {
                Guard.PositiveClock => "The exact comparison/negation rejects a positive clock before endpoint/work creation; the originating constructor frame identifies this guard, not invalid options or a clock-getter failure.",
                Guard.DefaultStartCancellation => "The exact negation sends an uncanceled default token to Task.FromCanceled. Its first BCL frame and immediate Core StartAsync caller identify the invalid internal call, rather than a canceled public request.",
                Guard.NonStoppingStart => "The exact inverted stopping guard throws while stopping is false under the gate, after the disposed guard, so a valid live start is rejected.",
                _ => throw new InvalidOperationException("Unknown reviewed guard.")
            });
}
